record R(int X) {
 public static int Counter = 1;
 public static string Name { get; } = "record";
 static R() { Print("record-init"); Counter++; }
}
model M { public static string Name = "model"; int N; }
void Main() {
 var r = new R(1); var hash = r.GetHashCode(); R.Counter = 10;
 var copy = r with { X = 2 }; Print(r.X); Print(copy.X); Print(R.Counter);
 Print(hash == r.GetHashCode()); Print(r == new R(1)); Print(R.Name);
 var m = new M { N = 3 }; var n = m with { N = 4 };
 Print(M.Name); Print(m.N); Print(n.N);
}
